-- Reading of documents and the registry lookup (docs/design/20-reader-and-registry.md §7.1).
-- Generated by `prisma migrate diff` (the columns and the table), then extended by hand with what
-- Prisma cannot express:
--
-- 1. partner gets the registry's published name, registration date and end date (失効・取消); they
--    sit beside invoice_registration_status / invoice_registration_checked_at.
-- 2. external_api_usage: one row per call of an external API (a reading, a registry lookup), with
--    CHECK constraints on the service, the outcome and the counts.
-- 3. external_api_usage is append-only like audit_log: UPDATE / DELETE / TRUNCATE are rejected.

-- AlterTable
ALTER TABLE "partner" ADD COLUMN     "invoice_registered_on" DATE,
ADD COLUMN     "invoice_registration_ended_on" DATE,
ADD COLUMN     "invoice_registration_name" TEXT;

-- CreateTable
CREATE TABLE "external_api_usage" (
    "id" TEXT NOT NULL,
    "at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "service" TEXT NOT NULL,
    "provider" TEXT NOT NULL,
    "model" TEXT,
    "document_id" TEXT,
    "outcome" TEXT NOT NULL,
    "error" TEXT,
    "request_count" INTEGER NOT NULL DEFAULT 1,
    "item_count" INTEGER NOT NULL DEFAULT 0,
    "input_tokens" INTEGER NOT NULL DEFAULT 0,
    "output_tokens" INTEGER NOT NULL DEFAULT 0,
    "cost_nano_usd" BIGINT NOT NULL DEFAULT 0,
    "actor" TEXT NOT NULL,

    CONSTRAINT "external_api_usage_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "external_api_usage_service_at_idx" ON "external_api_usage"("service", "at");

-- AddForeignKey
ALTER TABLE "external_api_usage" ADD CONSTRAINT "external_api_usage_document_id_fkey" FOREIGN KEY ("document_id") REFERENCES "document"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ---------------------------------------------------------------------------
-- CHECK constraints
-- ---------------------------------------------------------------------------

ALTER TABLE "external_api_usage"
  ADD CONSTRAINT "external_api_usage_service" CHECK ("service" IN ('reader', 'registry')),
  ADD CONSTRAINT "external_api_usage_outcome" CHECK ("outcome" IN ('ok', 'failed')),
  ADD CONSTRAINT "external_api_usage_counts_nonnegative" CHECK (
    "request_count" >= 0 AND "item_count" >= 0 AND "input_tokens" >= 0
    AND "output_tokens" >= 0 AND "cost_nano_usd" >= 0
  );

-- ---------------------------------------------------------------------------
-- external_api_usage: append-only (UPDATE / DELETE / TRUNCATE rejected)
-- ---------------------------------------------------------------------------

CREATE FUNCTION "ledger_external_api_usage_reject_change"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'ledger guard: external_api_usage is append-only (% of % rejected)', TG_OP, OLD."id";
END;
$$;

CREATE TRIGGER "external_api_usage_reject_change"
  BEFORE UPDATE OR DELETE ON "external_api_usage"
  FOR EACH ROW EXECUTE FUNCTION "ledger_external_api_usage_reject_change"();

CREATE TRIGGER "external_api_usage_reject_truncate"
  BEFORE TRUNCATE ON "external_api_usage"
  FOR EACH STATEMENT EXECUTE FUNCTION "ledger_reject_truncate"();
